import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String str = scanner.next();
        StringBuilder outputStr = new StringBuilder();
        outputStr.append(str.charAt(0));
        int atMarker = 0;
        int idx = 1;
        while (idx < str.length()) {
            String threeChars = "";
            String twoChars = "";
            if (idx + 2 <= str.length()) {
                threeChars = str.substring(idx, idx + 3);
            }
            if (idx + 1 <= str.length()) {
                twoChars = str.substring(idx, idx + 2);
            }
            if (threeChars.equals("dot") && idx != str.length() - 3) {
                idx += 3;
                outputStr.append('.');
            } else if (twoChars.equals("at") && atMarker == 0) {
                atMarker = 1;
                idx += 2;
                outputStr.append('@');
            } else {
                outputStr.append(str.charAt(idx));
                idx += 1;
            }
        }
        System.out.println(outputStr.toString());
        scanner.close();
    }
}
